<section class="panel"><div class="panel-heading"><div><span class="eyebrow">ADMINISTRATION</span><h2>Activity history <span class="count"><?= $total ?></span></h2></div></div><form class="admin-filters"><div><label for="q">Search staff, record or action</label><input id="q" name="q" type="search" value="<?= e($q) ?>"></div><div><label for="type">Content area</label><select id="type" name="type"><option value="">All areas</option><?php foreach(App\Controllers\AdminController::TYPES+['inquiries'=>'Inquiry inbox','settings'=>'Settings','account'=>'Account'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $type===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="btn">Filter</button><a class="btn" href="<?= url('admin/activity') ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>When</th><th>Staff</th><th>Action</th><th>Area</th><th>Record</th></tr></thead><tbody><?php foreach($rows as $event): ?><tr><td><?= e($event['created_at']) ?></td><td><?= e($event['actor']) ?></td><td><?= e($event['action']) ?></td><td><?= e(App\Controllers\AdminController::TYPES[$event['content_type']]??ucfirst($event['content_type'])) ?></td><td><?= e($event['record_label']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">No activity found. Saved content changes and inquiry updates are recorded here.</td></tr><?php endif; ?></tbody></table></div><?php $listPath='admin/activity';$filters=['q'=>$q,'type'=>$type];require BASE_PATH.'/app/Views/partials/admin-pagination.php'; ?></section>